{
  "name": "arggon-opencode2-scheduled-tasks",
  "version": "0.1.0",
  "description": "Cron-style scheduled agent tasks for OpenCode V2: declarative job files, tick loop, persistent per-job sessions, cost-bounded misfire handling. Inspired by jdormit/opencode-tasks (MIT, Jeremy Dormitzer) - see the README Acknowledgements.",
  "license": "MIT",
  "author": "Arggon",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Arggon/opencode-scheduled-tasks.git"
  },
  "homepage": "https://github.com/Arggon/opencode-scheduled-tasks#readme",
  "bugs": {
    "url": "https://github.com/Arggon/opencode-scheduled-tasks/issues"
  },
  "keywords": [
    "automation",
    "cron",
    "opencode",
    "opencode-plugin",
    "opencode-v2",
    "schedule",
    "scheduler",
    "scheduler-plugin"
  ],
  "type": "module",
  "main": "./src/index.ts",
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src/index.ts",
    "README.md"
  ],
  "scripts": {
    "test": "vitest run",
    "test:watch": "vitest",
    "typecheck": "tsc --noEmit",
    "check": "npm run typecheck && npm run test"
  },
  "devDependencies": {
    "@types/node": "^22.9.0",
    "tsx": "^4.23.15",
    "typescript": "^5.6.0",
    "vitest": "^4.1.11"
  },
  "optionalDependencies": {
    "yaml": "^2.9.1"
  }
}
